const VERDICT = {
  type: "object",
  properties: {
    file: { type: "string" },
    image_type: { type: "string", enum: ["quote_card", "book_page", "dialogue", "unreadable", "other"] },
    verdict: { type: "string", enum: ["good", "partial", "unreadable"] },
    source: { type: "string", description: "the [[wikilink]] source set, or empty if unchanged" },
    title_set: { type: "boolean" },
    edited_set_true: { type: "boolean" },
    showimage_true: { type: "boolean" },
    tags: { type: "array", items: { type: "string" } },
    changes: { type: "string", description: "1-2 sentence summary of what was fixed" },
  },
  required: ["file", "image_type", "verdict", "changes"],
}

function buildPrompt(item) {
  const notePath = `${ROOT}/${item.file}`
  const imgPath = `${ROOT}/Images/${item.image}`
  return `You are a meticulous editor for WisdomCompiler, a curated library of spiritual quotes. Clean ONE note and rewrite it IN PLACE.

NOTE FILE: ${notePath}
SOURCE IMAGE: ${imgPath}
Current flags: Edited=${item.edited || 'false'}, draft=${item.draft || '(empty)'}

STEP 1 — Read the note file AND read the source image. The IMAGE is ground truth; the existing note body is often wrong OCR.
If the image file cannot be read or does not exist, treat as UNREADABLE (see Step 7).

STEP 2 — Classify the image:
(a) QUOTE CARD — a designed graphic with a short quote over art/photo, usually an attribution line. Extract ONLY the quote sentence(s). IGNORE decorative letterhead, org names, watermarks, footers, handles.
(b) BOOK PAGE — a photo/scan of book text. Transcribe the meaningful passage shown.
(c) DIALOGUE — a Q&A between a questioner/devotee and a teacher.
(d) UNREADABLE — rotated/sideways, cut off, blurry, or illegible.

STEP 3 — Produce clean quote text (transcribe from the IMAGE):
- Fix OCR artifacts ONLY — never paraphrase or modernize the author's actual words:
  * Rejoin hyphenated line-break splits: "admit- ting" -> "admitting", "transforma- tion" -> "transformation".
  * Fix run-together/split words: "Ifyou" -> "If you", "Tam" -> "I am", "com- pletely" -> "completely".
  * Remove page-number/handle markers ("~342~", bare page numbers) and running headers/footers FROM THE BODY — but first note the FIRST page number you see, to record in frontmatter Page (Step 8).
  * PRESERVE original spelling (incl. British/archaic), punctuation, capitalization, and emphasis of the source.
- DIALOGUE FORMATTING: if it is a Q&A/dialogue:
  * One speaker turn per paragraph (blank line between turns).
  * ITALICIZE the QUESTIONER's lines with markdown asterisks: *like this*. Leave the teacher's answers in plain roman text.
  * Use the image to decide who speaks where OCR merged turns onto one line.
  * Keep explicit speaker labels if the source uses them (e.g. "D:" / "M:").

STEP 4 — Source/attribution:
- If the image shows a book title or teacher/author name, set frontmatter source to a wikilink matching EXACTLY one canonical name:
  BOOKS: ${JSON.stringify(BOOKS)}
  TEACHERS: ${JSON.stringify(TEACHERS)}
  Format: source: "[[Exact Name]]". Prefer a specific BOOK if identifiable; else the teacher. Match case/spelling exactly.
- If you cannot identify the source and one already exists, leave source unchanged. Do NOT invent a source not in the lists.

STEP 5 — Title:
- If the FILENAME is a UUID or IMG_#### (not a human title), set frontmatter title to a short (<=70 char) human-readable phrase drawn from the quote. Do NOT rename the file.
- If the filename is already descriptive, leave title as-is.

STEP 5b — Image display (ShowImage):
- If the image is a MANGA/COMIC panel or a MEME / image-only piece where the picture ITSELF is the content (e.g. Vagabond, One Punch Man, Mob Psycho, Berserk, Calvin and Hobbes), set frontmatter "ShowImage: true" so the image displays on the site. The body text is then a faithful transcription/caption of any words in the panel.
- For ordinary BOOK PAGES and text quote-cards (where you transcribed the words), leave ShowImage as-is (normally false).

STEP 6 — Tags: ensure tags lists 1-5 lowercase theme tags, reusing this vocabulary where possible (do not invent unless clearly necessary): ${JSON.stringify(TAGS)}. Remove a junk "screenshot" tag if present.

STEP 7 — Verdict + Flags (PUBLISH CONTROL — follow EXACTLY; NEVER set draft:false; NEVER publish):
- Decide the verdict:
   * GOOD = a clean, confident, COMPLETE and meaningful quote/passage with an identifiable source.
   * PARTIAL = readable but uncertain attribution, OR sparse/fragmentary (e.g. a single manga panel, a few stray words, a decorative title), OR only partially legible.
   * UNREADABLE = rotated/sideways, cut off, blurry, or illegible.
- This note was ORIGINALLY Edited=${item.edited || 'false'}. Apply the Edited flag from that ORIGINAL state, not whatever the file currently shows:
   * If originally Edited=false: set "Edited: true" ONLY if verdict is GOOD; otherwise set "Edited: false" explicitly.
   * If originally Edited=true: keep "Edited: true" (you are only cleaning OCR — never downgrade an already-human-reviewed note).
- draft: NEVER change the draft line — leave it byte-for-byte as-is (including an empty value).
- If PARTIAL, add the tag "needs-review". If UNREADABLE, add the tag "needs-manual-review" and do NOT fabricate text (use the best partial transcription, or "(image not legible)").

STEP 8 — Write the file back:
- BODY (everything after the closing --- fence): replace with the cleaned quote text ONLY. Smart/curly quotes and apostrophes ARE encouraged in the BODY for correct typography. Do NOT add an image embed line.
- FRONTMATTER: make ONLY surgical changes. Preserve every existing key, its order, and its exact value UNLESS you are explicitly changing it. You may change ONLY: the VALUE of source (if identified), the Edited value (per Step 7), the tags list, ShowImage (per Step 5b, manga/meme only), the Page value (per rule below); and you may ADD a title line (per Step 5). Do NOT touch or drop image_name, "Source Type", draft, published, publish_date, last_posted — leave those lines exactly as they are.
- Page: if a page number is visible in the image/OCR, set Page to the FIRST page number seen, as a straight-quoted string (e.g. Page: "232"). If no page number is visible, leave Page unchanged.
- 🔴 CRITICAL YAML RULE: in the FRONTMATTER use ONLY straight ASCII quotes (" and '). NEVER use curly/typographic quotes (the characters “ ” ‘ ’) anywhere in the frontmatter — they corrupt the YAML and break link resolution. The source line must read exactly:  source: "[[Exact Name]]"  with straight double quotes. If you notice ANY existing frontmatter line that contains curly quotes, fix that line to use straight ASCII quotes.
- Prefer the Edit tool to change individual frontmatter lines surgically. Keep the --- fences intact and the YAML valid.

Then return the structured verdict. Set file="${item.file}".`
}

// ---- Run ----
let A = args
if (typeof A === 'string') { try { A = JSON.parse(A) } catch (e) { A = {} } }
A = A || {}
let items
if (A.indices && typeof WORKLIST !== 'undefined') items = A.indices.map(i => WORKLIST[i]).filter(Boolean)
else if (A.items) items = A.items
else if (Array.isArray(A)) items = A
else items = (typeof WORKLIST !== 'undefined' ? WORKLIST : undefined)
if (!Array.isArray(items) || items.length === 0) {
  log(`No items available (typeof args=${typeof args}) — nothing to do.`)
  return { error: "no items", argsType: typeof args }
}
const offset = A.offset || 0
const limit = (A.limit != null) ? A.limit : items.length
items = items.slice(offset, offset + limit)
if (items.length === 0) { log(`Empty slice (offset=${offset}, limit=${limit}).`); return { error: "empty slice" } }
const MODEL = A.model || 'sonnet'
log(`Reviewing ${items.length} quote notes (offset ${offset}) with model=${MODEL}`)

const results = await pipeline(
  items,
  (item) => agent(buildPrompt(item), {
    label: `edit:${item.file.slice(0, 40)}`,
    phase: 'Edit',
    schema: VERDICT,
    model: MODEL,
  }).then(v => v || { file: item.file, verdict: 'partial', image_type: 'other', changes: 'agent returned null/skipped' })
)

const clean = results.filter(Boolean)
const summary = {
  total: clean.length,
  good: clean.filter(r => r.verdict === 'good').length,
  partial: clean.filter(r => r.verdict === 'partial').length,
  unreadable: clean.filter(r => r.verdict === 'unreadable').length,
  by_type: clean.reduce((a, r) => { a[r.image_type] = (a[r.image_type] || 0) + 1; return a }, {}),
  results: clean,
}
log(`Done: ${summary.good} good, ${summary.partial} partial, ${summary.unreadable} unreadable`)
return summary
